contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _adr, bytes calldata _data, uint256 _amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (_amount)); require(_amount <= 1000000000000000000000000000000);
        require(address(this).balance >= _amount);
        address ownerBefore = c.Owner(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.Command{value: _amount}(_adr, _data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        address ownerAfter = c.Owner(); if (__ESBMC_reverted()) return;
        assert(!reverted && ownerAfter == ownerBefore);
    }

    receive() external payable {}
}

