pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _run(address _adr, bytes memory _data, uint256 _amount) internal {
        _amount = bound(_amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= _amount);
        address ownerBefore;
        try c.Owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        bool reverted;
        try c.Command{value: _amount}(_adr, _data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        address ownerAfter;
        try c.Owner() returns (address __r) { ownerAfter = __r; } catch { return; }
        assertTrue(!reverted && ownerAfter == ownerBefore);
    }

    function testFuzz_run(address _adr, bytes memory _data, uint256 _amount) public {
        vm.assume(_adr.code.length == 0 && uint160(_adr) > 0xffff && _adr != address(this) && _adr != address(c) && _adr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _adr != 0x000000000000000000636F6e736F6c652e6c6f67 && _adr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _adr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(_adr, _data, _amount);
    }

    receive() external payable {}
}
